const fieldMeta=(prompt,k)=>{const inner=k.slice(1,-1);const caps=/^[A-Z0-9_ ]+$/.test(inner);const line=(prompt.split('\n').find(l=>l.includes(k))||'');let pre=line.slice(0,line.indexOf(k)).replace(/\*\*/g,'').replace(/^[\s\-*#>\d.]+/,'').replace(/[:\s(]+$/,'');if(pre.length>48)pre=pre.slice(-48).replace(/^\S*\s/,'');const human=caps?inner.toLowerCase().replace(/_/g,' ').replace(/^./,c=>c.toUpperCase()):'';const label=LABELS[k]||(pre.length>=2&&!/\($/.test(pre)&&!/extending/.test(pre)?pre:(human||'Details'));const ex=caps?'':inner.replace(/^e\.g\.\s*/,'').replace(/^SPECIFY:\s*/,'').replace(/,?\s*etc\.?$/,'').replace(/,?\s*for example:?$/,'');const parts=ex.split(/,\s*/);const vague=/^(if |any |main |typically |how will|user behavior|qualitative)/i.test(ex);const hint=!ex||vague||LABELS[k]&&/^Describe/.test(inner)?'':'e.g. '+parts.slice(0,2).join(', ');return{label,hint,long:/^(DESCRIBE|LIST|PASTE)/.test(inner)||/^Describe/.test(inner)}};
