const USE={'user-persona-generator':'Build 3 to 5 personas from what you know about your users.','user-journey-mapping':'Map one persona\'s path to one goal and rank the pain points.','wireframe-prototyper':'List every screen and state, then plan flows at low fidelity.','html-structure-generator':'Turn each key screen into landmarks and a heading outline.','universal-ui-design-methodology':'Set the token architecture and color reasoning for the brand.','design-system-generator':'Generate tokens, spacing, type and component specs.','color-scheme-generator':'Extend brand colors into ramps and tested contrast pairs.','typography-selection':'Pick web-licensed fonts and a baseline type scale.','mobile-design-philosophy':'Add touch targets, mobile type and platform rules.','css-architecture':'Decide file structure, naming and how tokens reach the CSS.','breakpoint-strategy':'Choose breakpoints from where your content breaks.','mobile-first-layout':'Build page layouts from 320px up.','react-components-generator':'Generate components if your stack is React.','vue-component-generator':'Generate components if your stack is Vue 3.','angular-component-generator':'Generate components if your stack is Angular.','web-components-generator':'Generate framework-free custom elements.','micro-interactions':'Design hover, press and feedback states under 300ms.','loading-animations':'Match loading indicators to real wait times.','aria-implementation':'Add correct roles and states to custom widgets.','keyboard-navigation':'Audit tab order, focus and key patterns.','screen-reader-optimization':'Fix reading order, labels and live announcements.','color-contrast-testing':'Check every color pair in every theme.','usability-testing-script':'Script a moderated test of your key flows.','cross-device-testing':'Plan device, browser and network testing.','performance-audit':'Audit Core Web Vitals and fix by impact.'};
const PREP=[['Write a one-paragraph brief','Who the product is for, the problem it solves, the goal of this project and how you will know it worked.'],['Collect your constraints','Brand assets, any existing design system, tech stack, browser support, deadline and team size.'],['Choose the framework early','It decides which component prompt you use in phase 5 and how the CSS is organized.'],['Set quality targets up front','A WCAG level (AA is the usual minimum) and a performance budget, so every prompt can be told about them.'],['Gather real content','Real copy, data and images, or clearly labelled placeholders. Prompts give better output with real material.'],['Pick a design direction','Write a short DESIGN.md or brand brief, and decide whether the anti-slop rules apply during the build or as an audit.'],['Name the project document','This page is the project document. The name titles the file and fills [PRODUCT_NAME] and [BRAND_NAME].']].map(([h,t],i)=>({h,t,n:String(i+1).padStart(2,'0')}));
